-- 原interaction的审批人证据；pending/answered仍由原CAS拥有。
CREATE TABLE interaction_votes(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,interaction_id TEXT NOT NULL,subject_id TEXT NOT NULL,revocation_epoch BIGINT NOT NULL CHECK(revocation_epoch>=0),expected_revision BIGINT NOT NULL CHECK(expected_revision>=0),approved BOOLEAN NOT NULL,request_json TEXT NOT NULL CHECK(octet_length(request_json)<=4096),created_at_ms BIGINT NOT NULL,PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,interaction_id,subject_id),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid,interaction_id) REFERENCES interactions(organization_id,tenant_id,project_id,agent_uid,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(organization_id,tenant_id,subject_id) REFERENCES principals(organization_id,tenant_id,subject_id) DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE interaction_votes ENABLE ROW LEVEL SECURITY;
ALTER TABLE interaction_votes FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON interaction_votes USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
CREATE TRIGGER immutable_interaction_vote BEFORE UPDATE OR DELETE ON interaction_votes FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();
CREATE TABLE identity_management_receipts(organization_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,agent_uid TEXT NOT NULL,operation_id TEXT NOT NULL,command_digest TEXT NOT NULL CHECK(length(command_digest)=64),actor_id TEXT NOT NULL,result_json TEXT NOT NULL CHECK(octet_length(result_json)<=65536),PRIMARY KEY(organization_id,tenant_id,project_id,agent_uid,operation_id),FOREIGN KEY(organization_id,tenant_id,project_id,agent_uid) REFERENCES agents(organization_id,tenant_id,project_id,uid) DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE identity_management_receipts ENABLE ROW LEVEL SECURITY;
ALTER TABLE identity_management_receipts FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON identity_management_receipts USING(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true)) WITH CHECK(organization_id=current_setting('agent.organization_id',true) AND tenant_id=current_setting('agent.tenant_id',true) AND project_id=current_setting('agent.project_id',true) AND agent_uid=current_setting('agent.agent_uid',true));
CREATE TRIGGER immutable_identity_receipt BEFORE UPDATE OR DELETE ON identity_management_receipts FOR EACH ROW EXECUTE FUNCTION reject_canonical_rewrite();
